package app.rwun;
import android.content.Context;import java.nio.file.Files;import java.time.*;import java.util.*;import org.json.*;
public final class V1HostTest {
 static int n;static void check(boolean c,String why){n++;if(!c)throw new AssertionError(why);}static void invalid(JSONObject d)throws Exception{boolean rejected=false;try{V1State.validate(d);}catch(Exception e){rejected=true;}check(rejected,"invalid v1 rejected");}
 public static void main(String[] args)throws Exception{
  LocalDate today=LocalDate.of(2026,10,18);JSONObject d=V1State.empty();V1State.event(d,"app_open",today);check(!d.has("events"),"default off");d.put("metrics",true);V1State.event(d,"app_open",today.minusDays(90));V1State.event(d,"app_open",today);check(d.getJSONObject("events").length()==1,"90 day retention");for(int i=0;i<3;i++)V1State.event(d,"plan_created",today);check(d.getJSONObject("events").getJSONObject(today.toString()).getInt("plan_created")==3,"bounded counters");check(V1State.report(d,today).contains("Active days: 1 / 7; 1 / 28"),"active days not opens");V1State.validate(d);
  for(String bad:List.of("{\"metrics\":\"true\"}","{\"events\":[]}","{\"activities\":{}}","{\"unknown\":1}","{\"events\":{\"2026-10-18\":{\"gps_route\":1}}}","{\"events\":{\"2026-10-18\":{\"app_open\":4294967296}}}","{\"events\":{\"2026-10-18\":{\"app_open\":1.5}}}"))invalid(new JSONObject(bad));
  JSONObject activity=new JSONObject().put("id","ride-1").put("date",today.toString()).put("type","Cycling").put("minutes",60).put("effort",7).put("completed",false);JSONObject activities=new JSONObject().put("activities",new JSONArray().put(activity));V1State.validate(activities);check(V1State.activities(activities).size()==1,"activity read");for(Object bad:List.of(-1,1.2,4294967356L,"60")){JSONObject copy=new JSONObject(activities.toString());copy.getJSONArray("activities").getJSONObject(0).put("minutes",bad);invalid(copy);}JSONArray overloaded=new JSONArray();for(int i=0;i<11;i++)overloaded.put(new JSONObject(activity.toString()).put("id","ride-"+i));invalid(new JSONObject().put("activities",overloaded));JSONObject dup=new JSONObject().put("activities",new JSONArray().put(activity).put(activity));invalid(dup);
  var hard=new WeekBalance.Other("a",today,"Cycling",60,7,false);var easy=new WeekBalance.Other("b",today,"Gym",30,3,true);var run=new WeekBalance.Running("run",today.plusDays(1),"Intervals");check(WeekBalance.conflicts(List.of(run),List.of(hard),today,today.plusDays(7)).size()==1,"adjacent hard conflict");check(WeekBalance.conflicts(List.of(run),List.of(easy),today,today.plusDays(7)).isEmpty(),"easy not hard");check(WeekBalance.conflicts(List.of(new WeekBalance.Running("r",today,"Easy run")),List.of(easy),today,today.plusDays(1)).size()==1,"same day visible");check(WeekBalance.conflicts(List.of(new WeekBalance.Running("r",today.plusDays(3),"Long easy run")),List.of(hard),today,today.plusDays(7)).isEmpty(),"spaced sessions");check(WeekBalance.conflicts(List.of(run),List.of(hard),today.minusDays(7),today).isEmpty(),"half open date window");
  Context c=new Context(Files.createTempDirectory("rwun-v1").toFile());RunStore store=new RunStore(c);store.v1(activities);JSONObject state=store.v1();state.put("metrics",true).put("events",d.getJSONObject("events"));store.v1(state);check(store.v1().getBoolean("metrics"),"consent persists");JSONObject portable=store.backupPreferences();JSONObject exported=new JSONObject(portable.getString("v1"));check(!exported.has("events")&&!exported.getBoolean("metrics"),"metrics excluded from backup");check(exported.getJSONArray("activities").length()==1,"activities included");store.restorePreferences(portable);check(!store.v1().optBoolean("metrics")&&V1State.activities(store.v1()).size()==1,"restore keeps activity without opting in");JSONObject imported=new JSONObject(portable.toString());imported.put("v1",state.toString());store.restorePreferences(imported);check(!store.v1().optBoolean("metrics")&&!store.v1().has("events"),"restore cannot opt in from a foreign backup");
  for(int days=2;days<=5;days++)for(int offset=0;offset<7;offset++)for(boolean returning:new boolean[]{false,true}){
   var cfg=new PlanEngine.Config(8,days,12,5,today.plusDays(offset));var profile=new PaceProfile(5,0,false);var preview=OnboardingPlan.sessions(cfg,profile,returning);store.createPlan(cfg,profile,returning);var actual=store.plannedSessions();check(preview.size()==actual.size(),"preview count");for(int i=0;i<preview.size();i++)check(preview.get(i).equals(actual.get(i)),"preview equals persisted first week and all weeks");if(returning)check(actual.get(0).title().equals("Run / walk"),"return starts in first week");
  }
  store.add(new RunStore.Run("old",today.toString(),2,20));store.adapt(new AdaptiveCoach.Advice(0,true,"Pain"));store.createPlan(new PlanEngine.Config(8,3,12,5,today),new PaceProfile(5,0,false),true);check(store.resting()&&store.runs().size()==1,"creation preserves hold and history");store.checkpoint("pending");boolean pending=false;try{store.createPlan(new PlanEngine.Config(8,3,12,5,today),new PaceProfile(5,0,false),false);}catch(IllegalStateException e){pending=true;}check(pending,"pending recording blocks replacement");
  System.out.println(n+" v1 assertions passed");
 }
}
